package org.fm1.wrapper;
import java.io.*;
import java.nio.*;
import java.util.*;
/** Standard MIDI file exchange for a single firmware pattern (no Android dependencies). */
final class MidiFile {
 static final int[] STEP_TICKS={480,240,120,60,160,80,960,1920,3840,7680};
 static final int[] DRUM_NOTES={36,35,38,39,42,46,44,37,40,43,48,49,51,70,63,56};
 static final class Note {int start,end,key,velocity,channel;Note(int t,int key,int vel,int ch){start=t;end=t+1;this.key=key;velocity=vel;channel=ch;}}
 static final class Track {String name;int ppq,bpm=90,end;ArrayList<Note> notes=new ArrayList<>();}
 static int readVar(ByteBuffer b){int v=0;for(int i=0;i<4;i++){int x=b.get()&255;v=(v<<7)|(x&127);if((x&128)==0)return v;}throw new IllegalArgumentException("Invalid MIDI time");}
 static List<Track> read(byte[] bytes){try{ByteBuffer b=ByteBuffer.wrap(bytes).order(ByteOrder.BIG_ENDIAN);if(bytes.length<14||b.getInt()!=0x4d546864)throw new IllegalArgumentException("Choose a standard MIDI file");int header=b.getInt(),format=b.getShort()&65535,count=b.getShort()&65535,ppq=b.getShort()&65535;if(header<6||header>bytes.length-8||format>1||count<1||count>64||ppq==0||(ppq&32768)!=0)throw new IllegalArgumentException("Use MIDI format 0/1 with PPQ timing");b.position(8+header);ArrayList<Track> tracks=new ArrayList<>();int bpm=90;
  for(int i=0;i<count;i++){if(b.getInt()!=0x4d54726b)throw new IllegalArgumentException("Invalid MIDI track");int n=b.getInt();if(n<0||n>b.remaining())throw new IllegalArgumentException("Truncated MIDI track");ByteBuffer t=b.slice().order(ByteOrder.BIG_ENDIAN);t.limit(n);b.position(b.position()+n);Track out=new Track();out.name="TRACK "+(i+1);out.ppq=ppq;HashMap<Integer,ArrayDeque<Note>> active=new HashMap<>();int ticks=0,running=0,events=0;while(t.hasRemaining()){if(++events>200000)throw new IllegalArgumentException("MIDI file is too large");int delta=readVar(t);if(ticks>Integer.MAX_VALUE-delta)throw new IllegalArgumentException("MIDI duration overflow");ticks+=delta;int status=t.get()&255;if(status<128){if(running==0)throw new IllegalArgumentException("Invalid MIDI running status");t.position(t.position()-1);status=running;}else if(status<240)running=status;
   if(status==255){int type=t.get()&255,len=readVar(t);if(len>t.remaining())throw new IllegalArgumentException("Truncated MIDI metadata");byte[] data=new byte[len];t.get(data);if(type==81&&len==3){int us=((data[0]&255)<<16)|((data[1]&255)<<8)|(data[2]&255);if(us>0)bpm=Math.max(40,Math.min(240,60000000/us));}if(type==3)out.name=new String(data,java.nio.charset.StandardCharsets.UTF_8);if(type==47)break;continue;}
   if(status==240||status==247){int len=readVar(t);if(len>t.remaining())throw new IllegalArgumentException("Truncated MIDI SysEx");t.position(t.position()+len);continue;}if(status>=240)throw new IllegalArgumentException("Unsupported MIDI event");int a=t.get()&127,c=status&15,kind=status&240,v=(kind==192||kind==208)?0:t.get()&127,key=c*128+a;
   if(kind==144&&v!=0){Note note=new Note(ticks,a,v,c);out.notes.add(note);active.computeIfAbsent(key,k->new ArrayDeque<>()).add(note);}else if(kind==128||kind==144){ArrayDeque<Note> notes=active.get(key);if(notes!=null&&!notes.isEmpty())notes.remove().end=Math.max(ticks,1);}
  }out.end=ticks;for(ArrayDeque<Note> notes:active.values())for(Note note:notes)note.end=Math.max(note.start+1,ticks);out.notes.sort(Comparator.comparingInt(x->x.start));tracks.add(out);}
  for(Track t:tracks)t.bpm=bpm;return tracks;
 }catch(BufferUnderflowException|IndexOutOfBoundsException e){throw new IllegalArgumentException("Truncated MIDI file",e);}}
 static byte[] pattern(Track track,int division,boolean drums){return pattern(track,division,drums,DRUM_NOTES);}
 static byte[] pattern(Track track,int division,boolean drums,int[] drumNotes){return pattern(track,division,drums,drumNotes,64);}
 static byte[] pattern(Track track,int division,boolean drums,int[] drumNotes,int maxSteps){if(maxSteps<1||maxSteps>128)throw new IllegalArgumentException("Invalid step limit");if(division<0||division>=STEP_TICKS.length)throw new IllegalArgumentException("Invalid division");double unit=STEP_TICKS[division]*track.ppq/480.0;byte[] out=new byte[12+maxSteps*10];ByteBuffer b=ByteBuffer.wrap(out).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0,0x3154504d);out[5]=(byte)(drums?1:0);out[6]=(byte)division;b.putShort(8,(short)track.bpm);int length=1;if(!drums)for(int i=0;i<maxSteps;i++)out[12+i*10+5]=2;int[] duration=new int[maxSteps];ArrayList<Note> notes=new ArrayList<>(track.notes);notes.sort(Comparator.<Note>comparingInt(n->(int)Math.round(n.start/unit)).thenComparing(Comparator.comparingInt((Note n)->n.velocity).reversed()));
  for(Note n:notes){int step=(int)Math.round(n.start/unit);if(step<0||step>=maxSteps)continue;int p=12+step*10,d=Math.max(1,(int)Math.round((n.end-n.start)/unit));length=Math.max(length,Math.min(maxSteps,step+d));if(drums){int lane=0,distance=1000;for(int i=0;i<drumNotes.length;i++)if(Math.abs(n.key-drumNotes[i])<distance){lane=i;distance=Math.abs(n.key-drumNotes[i]);}out[p+lane/8]|=1<<(lane%8);int lv=n.velocity<48?1:n.velocity<80?2:n.velocity>=112?3:0;out[p+2+lane/4]|=lv<<((lane%4)*2);}else{int count=out[p+4]&255;if(count>=4)continue;boolean duplicate=false;for(int i=0;i<count;i++)if((out[p+i]&127)==n.key)duplicate=true;if(duplicate)continue;out[p+count]=(byte)n.key;out[p+4]=(byte)(count+1);out[p+5]=0;out[p+7]=(byte)Math.max(out[p+7]&255,n.velocity);duration[step]=Math.max(duration[step],d);}}
  if(!drums)for(int i=0;i<maxSteps;i++)if(out[12+i*10+4]!=0)for(int d=1;d<duration[i]&&i+d<length&&out[12+(i+d)*10+4]==0;d++)out[12+(i+d)*10+5]=1;out[4]=(byte)length;return out;
 }
 static final class Event {int t;byte[] bytes;Event(int t,int... values){this.t=Math.max(0,t);bytes=new byte[values.length];for(int i=0;i<values.length;i++)bytes[i]=(byte)values[i];}}
 static void var(ByteArrayOutputStream out,int value){int buffer=value&127;while((value>>=7)>0){buffer<<=8;buffer|=(value&127)|128;}while(true){out.write(buffer&255);if((buffer&128)==0)break;buffer>>>=8;}}
 static byte[] write(int[][] notes,int[] duration,int[] velocity,int[] nudge,int[][] level,int[][] ratchet,int length,int division,int bpm,boolean drums){return write(notes,duration,velocity,nudge,level,ratchet,length,division,bpm,drums,DRUM_NOTES,64);}
 static byte[] write(int[][] notes,int[] duration,int[] velocity,int[] nudge,int[][] level,int[][] ratchet,int length,int division,int bpm,boolean drums,int[] drumNotes,int nudgeDiv){try{int unit=STEP_TICKS[division];ArrayList<Event> events=new ArrayList<>();int tempo=60000000/Math.max(40,bpm);events.add(new Event(0,255,81,3,tempo>>16,tempo>>8,tempo));for(int i=0;i<length;i++)for(int j=0;j<(drums?drumNotes.length:4);j++){if(drums?(notes[i][0]&(1<<j))==0:notes[i][j]<0)continue;int key=drums?drumNotes[j]:notes[i][j],lv=level[i][j],vel=drums?new int[]{96,32,64,127}[lv]:Math.max(1,Math.min(127,velocity[i]*(lv==1?35:lv==2?65:lv==3?125:100)/100)),count=ratchet[i][j]+1;int start=i*unit+nudge[i]*unit/nudgeDiv,end=(i+Math.max(1,duration[i]))*unit;for(int hit=0;hit<count;hit++){int at=start+hit*unit/count;events.add(new Event(at,drums?153:144,key,vel));events.add(new Event(count==1?end:at+unit/count/2,drums?137:128,key,0));}}events.sort(Comparator.comparingInt((Event e)->e.t).thenComparingInt(e->e.bytes[0]&255));ByteArrayOutputStream tr=new ByteArrayOutputStream();int last=0;for(Event e:events){var(tr,e.t-last);tr.write(e.bytes);last=e.t;}var(tr,Math.max(0,length*unit-last));tr.write(new byte[]{(byte)255,47,0});ByteArrayOutputStream out=new ByteArrayOutputStream();DataOutputStream d=new DataOutputStream(out);d.writeInt(0x4d546864);d.writeInt(6);d.writeShort(0);d.writeShort(1);d.writeShort(480);d.writeInt(0x4d54726b);d.writeInt(tr.size());tr.writeTo(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
}
